     /*
      * The methods of the first supertrait, as STypesUtil.allMethods gives them, except that the
      * trait of each declaration that the supertrait itself makes is named as the extends clause

    /* The same, from the instance t of the declared parameter type. */
    private static Type paramTypeAtInstance(Type declared, Type t) {
        if (!(declared instanceof TupleType) && t instanceof TupleType && !NodeUtil.isVoidType(t))
            return NodeFactory.makeTupleType(NodeUtil.getSpan(t), Useful.list(t));
        return t;
    }

    /* Whether paramTypeAtInstance made t the one boxed tuple of its method's JVM parameters. */
    private static boolean takesTupleBoxed(Type t) {
        return t instanceof TupleType && ((TupleType) t).getElements().size() == 1 &&
            ((TupleType) t).getElements().get(0) instanceof TupleType;
    }

    /*
     * Whether the dotted method func, which shadows the dotted method super_func at the
     * instance super_inst, takes as separate JVM parameters the elements of the tuple that
     * super_func takes as one value there.
     */
    private static boolean joinsTupleElements(Functional super_func, StaticTypeReplacer super_inst,
                                              Functional func) {
        if (func == null || !super_func.staticParameters().isEmpty() || !func.staticParameters().isEmpty())
            return false;
        if (!(super_func instanceof HasSelfType) || ((HasSelfType) super_func).selfPosition() != Naming.NO_SELF ||
            !(func instanceof HasSelfType) || ((HasSelfType) func).selfPosition() != Naming.NO_SELF)
            return false;
        Span span = NodeUtil.getSpan(super_func.name());
        Type from = paramTypeAtInstance(NodeUtil.getParamType(super_func.parameters(), span), super_inst);
        Type to = NodeUtil.getParamType(func.parameters(), span);
        return takesTupleBoxed(from) && to instanceof TupleType && !NodeUtil.isVoidType(to) && !takesTupleBoxed(to);
    }

    /*
     * An instance method thisName, of the signature thisSig whose one parameter is a tuple of
     * the type tuple, that calls fwdName of fwdClass on self with the tuple's elements, one JVM
     * parameter each, and answers its result: the bridge from a method that a generic trait
     * declares over a type parameter, at an instance that makes the parameter a tuple, to the
     * body that a type below it gives at the tuple type.
     */
    private void tupleElementsBridge(String thisName, String thisSig, TupleType tuple,
                                     String fwdClass, String fwdName, int fwdOp, String fwdSig) {
        MethodVisitor bmv = cw.visitMethod(ACC_PUBLIC, thisName, thisSig, null, null);
        bmv.visitCode();
        bmv.visitVarInsn(ALOAD, 0);
        bmv.visitVarInsn(ALOAD, 1);
        String owner = NamingCzar.jvmTypeDesc(tuple, thisApi(), false, true);
        List<Type> elements = tuple.getElements();
        int l = elements.size();
        for (int i = 0; i < l; i++) {
            Type t = elements.get(i);
            String m = InstantiatingClassloader.TUPLE_TYPED_ELT_PFX + (i + Naming.TUPLE_ORIGIN);
            String elementDesc = NamingCzar.jvmTypeDesc(t, thisApi(), true, true);
            if (i < l-1) bmv.visitInsn(DUP);
            bmv.visitMethodInsn(INVOKEINTERFACE, owner, m, "()" + elementDesc);
            InstantiatingClassloader.generalizedCastTo(bmv, NamingCzar.jvmTypeDesc(t, thisApi(), false, true));
            if (i < l-1) bmv.visitInsn(SWAP);
        }
        bmv.visitMethodInsn(fwdOp, fwdClass, fwdName, fwdSig);
        String returned = Naming.sigRet(thisSig);
        if (!returned.equals(Naming.sigRet(fwdSig)) ||
            returned.startsWith(Naming.TUPLE_OX) || returned.startsWith(Naming.ARROW_OX))
            InstantiatingClassloader.generalizedCastTo(bmv, returned);
        bmv.visitInsn(ARETURN);
        bmv.visitMaxs(Naming.ignoredMaxsParameter, Naming.ignoredMaxsParameter);
        bmv.visitEnd();
    }


    /**
      Fortress objects, compiled into classes, will class-inherit default methods
      defined in the first trait they extend (they are compiled to extend its
      trait default methods, which are in a class), but not default methods
      defined in subsequent extended traits.

      To fix this forwarding methods are added to the object to call the
      non-inherited default methods (where appropriate, meaning not defined
      in either the object itself or an earlier trait).

      Forwarding methods are also added to the compiled default-trait-methods
      classes, so that if they are inherited, they will supply all the necessary
      methods, and to ensure that the forwarding analysis is entirely local
      (that is, this trait/object, its first extended trait, and subsequent
      extended traits).

      includeCurrent is true for traits.  default-trait-method bodies are static,
      but instance methods are required for inheritance and dispatch.  For traits,
      in order to inherit the own (current) default methods, instance-to-static
      forwarding methods must be also be added.

      The conditions for adding a forwarding method are:

          1) Inherited through the second and subsequent supertraits -OR-
             includeCurrent and defined in the current trait.

          2) Are not also inherited through the first supertrait
             (due to joins in type hierarchy)

          3) Are not overridden by a method in the present trait or object

     Note the assumption that trait inheritance is normalized.
     If "A extends {B,C}" has been normalized,
     then B does not extend C and C does not extend B.
     That is, the extends clause is minimal.
     (There may be some issues with normalized inheritance and
      comprises clauses.)
    */
    private void dumpMethodChaining(String [] superInterfaces, boolean includeCurrent) {
        debug("Dump method chaining");
        /*
         * If the number of supertraits is 0, there is nothing to inherit.
         * If it is one, inheritance comes via the class hierarchy.
         * If not includeCurrent, then there are no own-trait methods to forward.
         *
         * In that case, there is nothing to do.
         */
        if (!includeCurrent && superInterfaces.length <= 1 && payloadObjectSuper == null) return;

        TraitType currentTraitObjectType = STypesUtil.declToTraitType(currentTraitObjectDecl);
        List<TraitTypeWhere> extendsClause = NodeUtil.getExtendsClause(currentTraitObjectDecl);
        Relation<IdOrOpOrAnonymousName, scala.Tuple3<Functional, StaticTypeReplacer, TraitType>>
            alreadyIncluded;
        /*
         * Initialize alreadyIncluded to empty, or to the inherited methods
         * from the first t
         */
        if (payloadObjectSuper != null || extendsClause.size() == 0 || !(extendsClause.get(0).getBaseType() instanceof TraitType)) {
            alreadyIncluded =
                new IndexedRelation<IdOrOpOrAnonymousName,
                             scala.Tuple3<Functional, StaticTypeReplacer, TraitType>>();
        } else {
//          alreadyIncluded = STypesUtil.inheritedMethods(extendsClause.subList(0,1), typeAnalyzer);
            alreadyIncluded = firstSupertraitMethods((TraitType)(extendsClause.get(0).getBaseType()));
	    debug("Already included: ", alreadyIncluded);
        }
	//        System.err.println("For " + currentTraitObjectType + " the already included methods are " + alreadyIncluded);
        /*
         * Apparently allMethods returns the transitive closure of all methods
         * declared in a particular trait or object and the types it extends.
         * Iterate over all of them, noting the ones with bodies, that are not
         * already defined in this type or the first extending type (those
         * defined in this type are conditional on includeCurrent).
         *
         * Note that extends clauses should be minimal by this point, or at
         * least as-if minimal; we don't want to be dealing with duplicated
         * methods that would not trigger overriding by the meet rule (if the
         * extends clause is minimal, and a method is defined twice in the
         * extends clause, then it needs to be disambiguated in this type).
         */
        /*
         * The methods to consider are those of this trait or object and of the types that it
         * extends, without each declaration that a type below its own replaces at the same
         * parameter types, self apart (Specification/basic/traits.tex, section "Method
         * Declarations").  The rule names one declaration of each such group whatever the
         * order of the gathered methods, so no method is written twice and the declaration
         * of the lowest type runs.
         */
        Relation<IdOrOpOrAnonymousName, scala.Tuple3<Functional, StaticTypeReplacer, TraitType>>
            toConsider = STypesUtil.allMethodsNotReplaced(currentTraitObjectType, typeAnalyzer);
        List<scala.Tuple5<Functional, StaticTypeReplacer, TraitType, Functional, TraitType>> hidden =
            STypesUtil.overriddenNotProvided(currentTraitObjectType, typeAnalyzer);
        Map<Functional, Functional> overriddenHere = overriddenNotProvided(hidden);
        debug("Considering chains for ", currentTraitObjectType, ": ", toConsider);
        for (edu.rice.cs.plt.tuple.Pair<IdOrOpOrAnonymousName,scala.Tuple3<Functional, StaticTypeReplacer, TraitType>>
                 assoc : toConsider) {
            scala.Tuple3<Functional, StaticTypeReplacer, TraitType> tup = assoc.second();
            TraitType tupTrait = tup._3();
            StaticTypeReplacer inst = tup._2();
            Functional fnl = (tup._1()); // better be true
            //System.err.println("  "+assoc.first()+" "+tupTrait+" "+fnl);
            /* Skip non-definitions. */
            if (!hasBodyInItsTrait(fnl, tupTrait)) {
                // need to worry about tighter definitions in implementing types.

                // need to worry about tighter definitions in implementing types.
                continue;
            }
            /* Skip a declaration that an override keeps this type from inheriting: a call at
             * its signature runs the override (dumpOverloadedMethodChaining). */
            if (overriddenHere.containsKey(fnl)) continue;

            List<StaticParam> static_parameters = fnl.staticParameters();

	    //            if (tupTrait.equals(currentTraitObjectType)) {
            if (typeAnalyzer.equiv(tupTrait, currentTraitObjectType)) {
                /* If defined in the current trait. */
                if (includeCurrent) {
                    // Trait, not object
                    generateForwardingFor(fnl, inst, currentTraitObjectType, tupTrait); // swapped
                    generateForwardingFor(fnl, fnl, true, inst, currentTraitObjectType, tupTrait, false); // swapped
                }
            } else {
                /* If not defined in the current trait. */
		boolean alreadyThere = false;

		/* Iterate over tuples for
		 * already-defined methods
		 * whose names match
		 * that of the method being considered (assoc.first()).
		 *
		 * If the trait of the method being considered,
		 * and the trait of any name-matching already included method
		 * match, then don't generate a wrapper.
		 *
		 * DOES THIS HAVE A BUG IN IT?  WHAT ABOUT OVERLOADED METHODS?
		 * Their names will match, but the parameter types need not.
		 */
		debug("For method ", assoc.first(), ", does any of these match: ", alreadyIncluded.matchFirst(assoc.first()));
		for (scala.Tuple3<Functional, StaticTypeReplacer, TraitType> tupAlready :
			 alreadyIncluded.matchFirst(assoc.first())) {
		    if (tupAlready._3().equals(tupTrait)) {
		        alreadyThere = true;
	            break;
		    }

		    StaticTypeReplacer str = tupAlready._2();
		    Type alreadyType = str.replaceIn(tupAlready._3());
		    if (typeAnalyzer.equiv(alreadyType,tupTrait)) {
			//System.err.println("    " + fnl + " already imported by first supertrait.");
			alreadyThere = true;
			break;
		    }
		}
		if (!alreadyThere) {
		    generateForwardingFor(fnl, inst, currentTraitObjectType, tupTrait); // swapped
		    generateForwardingFor(fnl, fnl, true, inst, currentTraitObjectType, tupTrait, false); // swapped
		}
	    }
        }
        overrideBridges(currentTraitObjectType, alreadyIncluded, hidden);
    }

    /*
     * Whether the trait that declares the method fnl holds a body for it.  A declaration read
     * from an imported api has no body there; unless it has the modifier abstract its body is
     * in the component that exports the api, as the checker's AbstractMethodChecker reads it.
     * A field's getter or setter has none.
     */
    private boolean hasBodyInItsTrait(Functional fnl, TraitType declaring) {
        if (fnl.body().isSome()) return true;
        if (fnl instanceof FieldGetterOrSetterMethod && ((FieldGetterOrSetterMethod) fnl).fnDecl().isNone())
            return false;
        return declaring.getName().getApiName().isSome() && !fnl.mods().isAbstract();
    }

    /*
     * Each declaration that a declaration with the modifier override keeps a trait or object, or
     * a type above it, from inheriting, and that the type does not provide, mapped to that
     * override, from the list that STypesUtil.overriddenNotProvided gives for the type (the
     * checker's table of what an override keeps from being inherited;
     * Specification/basic/traits.tex, section "Method Declarations").
     */
    private static Map<Functional, Functional> overriddenNotProvided(
            List<scala.Tuple5<Functional, StaticTypeReplacer, TraitType, Functional, TraitType>> hidden) {
        Map<Functional, Functional> result = new java.util.IdentityHashMap<Functional, Functional>();
        for (scala.Tuple5<Functional, StaticTypeReplacer, TraitType, Functional, TraitType> t : hidden)
            result.put(t._1(), t._4());
        return result;
    }

    /*
     * Stops where the bridge from the declaration p, at its instance inst, to the declaration
     * o that overrides it cannot be compiled yet: where either has static parameters of its
     * own, as a generic method is compiled to a closure finder; or where the current trait or
     * object has static parameters and the parameter types of p or o name a static parameter,
     * since at an instance that makes the two parameter types equal the class would hold the
     * bridge and the override under one signature.
     */
    private void checkOverrideCompilable(Functional p, StaticTypeReplacer inst, Functional o,
                                         OverloadingOracle oa) {
        if (!p.staticParameters().isEmpty() || !o.staticParameters().isEmpty())
            throw sayWhat(o.name(), "Can't compile an override of or by a method with static parameters of its own yet.");
        if (!currentTraitObjectDecl.getHeader().getStaticParams().isEmpty() &&
            (mentionsTypeVariable(inst.replaceInEverything(oa.getNoSelfDomainType(p))) ||
             mentionsTypeVariable(oa.getNoSelfDomainType(o))))
            throw sayWhat(o.name(), "Can't compile an override in a trait or object with static parameters, " +
                          "where its parameter types or the overridden declaration's name a static parameter, yet.");
    }

    /*
     * For each declaration that an override of a type above the trait or object tt keeps tt
     * from inheriting, where tt's class does not inherit the bridge of the class of the type
     * that declares the override, as it does through its first supertrait: a method at the
     * declaration's signature that forwards to the override, as that class has one
     * (dumpOverloadedMethodChaining).  first holds the methods that tt's first supertrait
     * gives its class, and hidden the list of STypesUtil.overriddenNotProvided for tt.  One
     * bridge for each overridden declaration.
     */
    private void overrideBridges(TraitType tt,
            Relation<IdOrOpOrAnonymousName, scala.Tuple3<Functional, StaticTypeReplacer, TraitType>> first,
            List<scala.Tuple5<Functional, StaticTypeReplacer, TraitType, Functional, TraitType>> hidden) {
        Set<Functional> viaFirst = Collections.newSetFromMap(new java.util.IdentityHashMap<Functional, Boolean>());
        for (scala.Tuple3<Functional, StaticTypeReplacer, TraitType> f : first.secondSet())
            viaFirst.add(f._1());
        Set<Functional> bridged = Collections.newSetFromMap(new java.util.IdentityHashMap<Functional, Boolean>());
        for (scala.Tuple5<Functional, StaticTypeReplacer, TraitType, Functional, TraitType> t : hidden) {
            if (typeAnalyzer.equiv(t._5(), tt) || viaFirst.contains(t._4()) || !bridged.add(t._1()))
                continue;
            checkOverrideCompilable(t._1(), t._2(), t._4(), new OverloadingOracle(typeAnalyzer));
            generateForwardingFor(t._1(), t._4(), false, t._2(), tt, tt, true);
        }
    }

    /*
     * The methods of the first supertrait, as STypesUtil.allMethods gives them, except that the
     * trait of each declaration that the supertrait itself makes is named as the extends clause
     * names it.  allMethods names that trait as the trait's own declaration does, and the
     * declaration of a trait of an imported api names it without the api; the trait table, made
     * over this component, does not find that name.  A declaration of a supertrait of the first
     * one keeps the name that allMethods gives it, the name of an extends clause.
     */
    private Relation<IdOrOpOrAnonymousName, scala.Tuple3<Functional, StaticTypeReplacer, TraitType>>
        firstSupertraitMethods(TraitType first) {
        Relation<IdOrOpOrAnonymousName, scala.Tuple3<Functional, StaticTypeReplacer, TraitType>> methods =
            STypesUtil.allMethods(first, typeAnalyzer);
        Option<TypeConsIndex> index = typeAnalyzer.traits().typeCons(first.getName());
        if (index.isNone() || !(index.unwrap() instanceof TraitIndex)) return methods;
        TraitIndex ti = (TraitIndex) index.unwrap();
        Set<Functional> own = Collections.newSetFromMap(new java.util.IdentityHashMap<Functional, Boolean>());
        own.addAll(ti.dottedMethods().secondSet());
        own.addAll(ti.functionalMethods().secondSet());
        own.addAll(ti.getters().values());
        own.addAll(ti.setters().values());
        Relation<IdOrOpOrAnonymousName, scala.Tuple3<Functional, StaticTypeReplacer, TraitType>> result =
            new IndexedRelation<IdOrOpOrAnonymousName, scala.Tuple3<Functional, StaticTypeReplacer, TraitType>>(false);

